css:
.nr2020-container {
  --nr-paper: #f5f2ea;
  --nr-card: #fffdf8;
  --nr-ink: #14203a;
  --nr-muted: #48536a;
  --nr-rule: #d6cfbf;
  --nr-navy: #1b2d52;
  --nr-navy-soft: #e6e9f1;
  --nr-brass: #7c5410;
  --nr-brass-soft: #f4ead6;
  --nr-red: #8f1f24;
  --nr-red-soft: #f7e3e2;
  --nr-green: #24603a;
  --nr-green-soft: #e2f0e6;
  --nr-serif: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif;
  --nr-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --nr-r: 4px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #14203a;
  background-color: #f5f2ea;
  max-width: 1160px;
  margin: 0 auto;
  padding: 24px 24px 32px;
  line-height: 1.5;
  font-size: 16px;
  box-sizing: border-box;
  color-scheme: light;
}
.nr2020-container *, .nr2020-container *::before, .nr2020-container *::after { box-sizing: border-box; }
.nr2020-container [hidden] { display: none !important; }
.nr2020-container h1, .nr2020-container h2, .nr2020-container h3, .nr2020-container p { margin: 0; }
.nr2020-container .nr-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

.nr2020-container .nr-mast { border-top: 6px double #1b2d52; border-bottom: 1px solid #1b2d52; padding: 10px 0 14px; margin-bottom: 18px; }
.nr2020-container .nr-mast-top { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; font-size: 0.78rem; letter-spacing: 0.14em; text-transform: uppercase; color: #48536a; padding-bottom: 10px; border-bottom: 1px solid #d6cfbf; margin-bottom: 14px; }
.nr2020-container .nr-conf { color: #7c5410; font-weight: 600; }
.nr2020-container .nr-mast-main { display: flex; justify-content: space-between; align-items: flex-end; gap: 18px; flex-wrap: wrap; }
.nr2020-container .nr-title { font-family: Georgia, "Iowan Old Style", "Palatino Linotype", "Times New Roman", serif; font-size: 2.3rem; font-weight: 700; line-height: 1.1; color: #1b2d52; letter-spacing: -0.01em; }
.nr2020-container .nr-sub { font-family: Georgia, "Times New Roman", serif; font-style: italic; color: #48536a; font-size: 1.05rem; margin-top: 6px; max-width: 62ch; }
.nr2020-container .nr-counter { display: flex; flex-direction: column; align-items: flex-end; min-width: 150px; color: #14203a; background-color: #f5f2ea; }
.nr2020-container .nr-counter-l { font-size: 0.75rem; letter-spacing: 0.14em; text-transform: uppercase; color: #48536a; }
.nr2020-container .nr-counter-n { font-family: Georgia, "Times New Roman", serif; font-size: 1.9rem; font-weight: 700; color: #1b2d52; line-height: 1.1; }
.nr2020-container .nr-counter-s { font-size: 0.95rem; font-weight: 600; color: #7c5410; }

.nr2020-container .nr-rail { list-style: none; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin: 16px 0 0; padding: 0; counter-reset: none; }
.nr2020-container .nr-rail li { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-top: 3px solid #d6cfbf; color: #48536a; background-color: #f5f2ea; font-size: 0.9rem; }
.nr2020-container .nr-rail li.is-done { border-top-color: #48536a; color: #14203a; background-color: #f5f2ea; }
.nr2020-container .nr-rail li.is-now { border-top-color: #7c5410; color: #14203a; background-color: #f5f2ea; font-weight: 700; }
.nr2020-container .nr-rail-n { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; border-radius: 50%; border: 1px solid currentColor; font-family: Georgia, serif; font-size: 0.85rem; flex: none; }
.nr2020-container .nr-rail li.is-now .nr-rail-n { background-color: #7c5410; color: #fffdf8; border-color: #7c5410; }
.nr2020-container .nr-rail li.is-done .nr-rail-n { background-color: #48536a; color: #fffdf8; border-color: #48536a; }

.nr2020-container .nr-obj { background-color: #fffdf8; color: #14203a; border: 1px solid #d6cfbf; border-left: 4px solid #1b2d52; border-radius: 4px; padding: 10px 16px; margin-bottom: 16px; }
.nr2020-container .nr-obj summary { cursor: pointer; font-family: Georgia, serif; font-weight: 700; color: #1b2d52; font-size: 1.05rem; min-height: 32px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.nr2020-container .nr-obj-now { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; font-weight: 600; font-size: 0.85rem; color: #7c5410; background-color: #f4ead6; padding: 2px 10px; border-radius: 999px; }
.nr2020-container .nr-obj-list { margin: 8px 0 6px; padding-left: 22px; display: grid; gap: 4px; font-size: 0.95rem; }
.nr2020-container .nr-obj-list li.is-focus { font-weight: 600; }
.nr2020-container .nr-obj-list li.is-focus::marker { color: #7c5410; }
.nr2020-container .nr-obj-how { font-size: 0.9rem; color: #48536a; }

.nr2020-container .nr-fourteen { background-color: #1b2d52; color: #f5f2ea; border-radius: 4px; padding: 14px 18px; margin-bottom: 16px; display: grid; gap: 8px; }
.nr2020-container .nr-fourteen .nr-h3 { color: #f4ead6; background-color: #1b2d52; font-family: Georgia, serif; font-size: 0.85rem; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 600; }
.nr2020-container .nr-people { display: flex; flex-wrap: wrap; gap: 6px; }
.nr2020-container .nr-person { width: 30px; height: 44px; flex: none; }
.nr2020-container .nr-person .nr-p-head, .nr2020-container .nr-person .nr-p-body { fill: none; stroke: #8d99b4; stroke-width: 2; }
.nr2020-container .nr-person.is-lit .nr-p-head, .nr2020-container .nr-person.is-lit .nr-p-body { fill: #e6c27a; stroke: #e6c27a; }
.nr2020-container .nr-fourteen-cap { font-family: Georgia, serif; font-size: 1.1rem; color: #f5f2ea; background-color: #1b2d52; }
.nr2020-container .nr-fourteen-cap strong { color: #e6c27a; background-color: #1b2d52; }

.nr2020-container .nr-kpis { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 0; margin-bottom: 18px; border-top: 1px solid #14203a; border-bottom: 1px solid #14203a; }
.nr2020-container .nr-kpi { background-color: #f5f2ea; color: #14203a; padding: 10px 12px; display: flex; flex-direction: column; gap: 2px; border-right: 1px solid #d6cfbf; }
.nr2020-container .nr-kpi:last-child { border-right: 0; }
.nr2020-container .nr-kpi-l { font-size: 0.75rem; letter-spacing: 0.06em; text-transform: uppercase; color: #48536a; }
.nr2020-container .nr-kpi-v { font-family: Georgia, "Times New Roman", serif; font-size: 1.6rem; font-weight: 700; color: #14203a; font-variant-numeric: tabular-nums; line-height: 1.2; }
.nr2020-container .nr-kpi-s { font-size: 0.8rem; color: #48536a; }
.nr2020-container .nr-kpi-s .nr-up { color: #24603a; font-weight: 700; }
.nr2020-container .nr-kpi-s .nr-down { color: #8f1f24; font-weight: 700; }
.nr2020-container .nr-kpi-score { background-color: #f4ead6; color: #14203a; }
.nr2020-container .nr-kpi-score .nr-kpi-v { color: #7c5410; }
.nr2020-container .nr-meter { display: block; height: 6px; background-color: #d6cfbf; border-radius: 3px; overflow: hidden; margin: 2px 0; }
.nr2020-container .nr-meter-fill { display: block; height: 100%; width: 0; background-color: #1b2d52; transition: width 0.4s ease; }

.nr2020-container .nr-memo { background-color: #fffdf8; color: #14203a; border: 1px solid #d6cfbf; border-radius: 4px; padding: 22px 26px 20px; margin-bottom: 14px; box-shadow: 0 1px 0 #d6cfbf, 0 6px 18px rgba(20, 32, 58, 0.06); }
.nr2020-container .nr-memo-date { font-size: 0.78rem; letter-spacing: 0.14em; text-transform: uppercase; color: #7c5410; font-weight: 600; margin-bottom: 4px; }
.nr2020-container .nr-h2 { font-family: Georgia, "Times New Roman", serif; font-size: 1.45rem; font-weight: 700; color: #1b2d52; margin-bottom: 8px; line-height: 1.25; }
.nr2020-container .nr-h3 { font-family: Georgia, serif; font-size: 1.05rem; font-weight: 700; color: #1b2d52; margin-bottom: 6px; }
.nr2020-container .nr-memo-body { display: grid; gap: 8px; font-size: 1rem; max-width: 78ch; }
.nr2020-container .nr-memo-body ul { margin: 0; padding-left: 20px; display: grid; gap: 4px; }
.nr2020-container .nr-voices { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 14px; }
.nr2020-container .nr-voice { margin: 0; padding: 4px 0 4px 14px; border-left: 3px solid #7c5410; color: #14203a; background-color: #fffdf8; }
.nr2020-container .nr-voice:nth-child(2) { border-left-color: #1b2d52; }
.nr2020-container .nr-voice p { font-family: Georgia, "Times New Roman", serif; font-style: italic; font-size: 1.02rem; }
.nr2020-container .nr-voice cite { display: block; font-style: normal; font-size: 0.82rem; color: #48536a; margin-top: 4px; }

.nr2020-container .nr-story { background-color: #f5f2ea; color: #14203a; border-top: 1px solid #d6cfbf; border-bottom: 1px solid #d6cfbf; padding: 8px 2px; margin-bottom: 16px; }
.nr2020-container .nr-story summary { cursor: pointer; font-weight: 600; color: #1b2d52; min-height: 32px; display: flex; align-items: center; }
.nr2020-container .nr-story-body { margin-top: 8px; display: grid; gap: 8px; font-size: 0.95rem; max-width: 80ch; }
.nr2020-container .nr-story-body ul { margin: 0; padding-left: 20px; }

.nr2020-container .nr-box { background-color: #fffdf8; color: #14203a; border: 1px solid #d6cfbf; border-radius: 4px; padding: 18px 20px; margin-bottom: 14px; }
.nr2020-container .nr-help { font-size: 0.9rem; color: #48536a; margin-bottom: 8px; display: block; }
.nr2020-container .nr-fs { border: 0; margin: 0 0 16px; padding: 0; min-width: 0; }
.nr2020-container .nr-fs:last-child { margin-bottom: 0; }
.nr2020-container .nr-legend { font-family: Georgia, serif; font-weight: 700; font-size: 1.05rem; color: #1b2d52; margin-bottom: 8px; padding: 0; display: block; }

.nr2020-container .nr-evidence { background-color: #f5f2ea; color: #14203a; border-radius: 4px; padding: 12px 16px; margin-bottom: 16px; }
.nr2020-container .nr-ev-list { margin: 0; padding-left: 22px; display: grid; gap: 6px; font-size: 0.95rem; }
.nr2020-container .nr-ev-src { font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: #7c5410; font-weight: 700; margin-right: 4px; }

.nr2020-container .nr-alloc { display: grid; gap: 6px; }
.nr2020-container .nr-alloc-row { display: grid; grid-template-columns: minmax(0, 1fr) 96px; align-items: center; gap: 12px; padding: 6px 0; border-bottom: 1px dotted #d6cfbf; }
.nr2020-container .nr-alloc-row label { font-size: 0.97rem; }
.nr2020-container .nr-alloc-bar { display: flex; height: 12px; margin-top: 10px; border-radius: 2px; overflow: hidden; background-color: #d6cfbf; }
.nr2020-container .nr-alloc-seg { display: block; height: 100%; }
.nr2020-container .nr-seg-0 { background-color: #8d99b4; }
.nr2020-container .nr-seg-1 { background-color: #7c5410; }
.nr2020-container .nr-seg-2 { background-color: #1b2d52; }
.nr2020-container .nr-seg-3 { background-color: #4f7a63; }
.nr2020-container .nr-alloc-total { font-size: 0.9rem; margin-top: 6px; color: #48536a; }
.nr2020-container .nr-alloc-total.is-bad { color: #8f1f24; font-weight: 700; }

.nr2020-container input[type="number"], .nr2020-container textarea { font: inherit; font-variant-numeric: tabular-nums; color: #14203a; background-color: #ffffff; border: 1px solid #8d8574; border-radius: 4px; padding: 8px 10px; min-height: 44px; width: 100%; }
.nr2020-container textarea { min-height: 64px; resize: vertical; }
.nr2020-container input:focus-visible, .nr2020-container textarea:focus-visible, .nr2020-container button:focus-visible, .nr2020-container summary:focus-visible { outline: 3px solid #7c5410; outline-offset: 2px; }

.nr2020-container .nr-opts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.nr2020-container .nr-opt { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border: 1px solid #d6cfbf; border-radius: 4px; background-color: #ffffff; color: #14203a; cursor: pointer; min-height: 44px; transition: border-color 0.15s ease, background-color 0.15s ease; }
.nr2020-container .nr-opt:hover { border-color: #48536a; background-color: #fbf8f1; }
.nr2020-container .nr-opt.is-on { border-color: #1b2d52; background-color: #e6e9f1; box-shadow: inset 4px 0 0 #1b2d52; }
.nr2020-container .nr-opt input { margin-top: 4px; width: 18px; height: 18px; flex: none; accent-color: #1b2d52; }
.nr2020-container .nr-opt input:focus-visible { outline: 3px solid #7c5410; outline-offset: 2px; }
.nr2020-container .nr-opt-body { display: flex; flex-direction: column; gap: 2px; }
.nr2020-container .nr-opt-body strong { font-weight: 700; color: #14203a; }
.nr2020-container .nr-opt-d { font-size: 0.9rem; color: #48536a; }
.nr2020-container .nr-tag { align-self: flex-start; margin-top: 4px; font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 700; color: #7c5410; background-color: #f4ead6; padding: 1px 8px; border-radius: 999px; }

.nr2020-container .nr-checks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.nr2020-container .nr-check { display: flex; gap: 10px; align-items: center; padding: 10px 12px; border: 1px solid #d6cfbf; border-radius: 4px; background-color: #ffffff; color: #14203a; cursor: pointer; min-height: 44px; }
.nr2020-container .nr-check:hover { border-color: #48536a; background-color: #fbf8f1; }
.nr2020-container .nr-check.is-on { border-color: #1b2d52; background-color: #e6e9f1; }
.nr2020-container .nr-check input { width: 18px; height: 18px; flex: none; accent-color: #1b2d52; }

.nr2020-container .nr-dial-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin: 6px 0 12px; }
.nr2020-container .nr-dial { display: flex; flex-direction: column; gap: 6px; padding: 12px 14px; border: 1px solid #d6cfbf; border-radius: 4px; background-color: #ffffff; color: #14203a; position: relative; }
.nr2020-container .nr-dial.is-moved { border-color: #1b2d52; box-shadow: inset 0 3px 0 #1b2d52; }
.nr2020-container .nr-dial-l { font-family: Georgia, serif; font-weight: 700; color: #1b2d52; }
.nr2020-container .nr-dial input[type="range"] { width: 100%; min-height: 44px; accent-color: #1b2d52; cursor: pointer; }
.nr2020-container .nr-dial input[type="range"]:focus-visible { outline: 3px solid #7c5410; outline-offset: 2px; }
.nr2020-container .nr-dial-o { font-weight: 600; min-height: 2.6em; color: #14203a; }
.nr2020-container .nr-dial-c { font-size: 0.8rem; color: #48536a; font-variant-numeric: tabular-nums; }
.nr2020-container .nr-dial-c .nr-mandate { color: #7c5410; font-weight: 700; }
.nr2020-container .nr-budget { display: grid; gap: 6px; }
.nr2020-container .nr-budget-bar { height: 8px; background-color: #d6cfbf; border-radius: 4px; overflow: hidden; }
.nr2020-container .nr-budget-fill { display: block; height: 100%; width: 0; background-color: #1b2d52; transition: width 0.3s ease; }
.nr2020-container .nr-budget.is-over .nr-budget-fill { background-color: #8f1f24; }
.nr2020-container .nr-budget-t { font-size: 0.92rem; color: #14203a; font-variant-numeric: tabular-nums; }
.nr2020-container .nr-budget.is-over .nr-budget-t { color: #8f1f24; font-weight: 700; }

.nr2020-container .nr-signals-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 8px; }
.nr2020-container .nr-signal { border-top: 3px solid #8f1f24; padding: 10px 2px 0; color: #14203a; background-color: #fffdf8; }
.nr2020-container .nr-signal b { display: block; font-family: Georgia, serif; font-size: 1.6rem; color: #8f1f24; line-height: 1.15; }
.nr2020-container .nr-signal span { font-size: 0.92rem; }

.nr2020-container .nr-forecast { background-color: #f4ead6; color: #14203a; border-color: #d9c39b; }
.nr2020-container .nr-forecast .nr-h3 { display: flex; align-items: center; gap: 8px; }
.nr2020-container .nr-seal { width: 22px; height: 22px; border-radius: 50%; background-color: #7c5410; box-shadow: inset 0 0 0 3px #f4ead6, 0 0 0 2px #7c5410; flex: none; }
.nr2020-container .nr-field { display: grid; gap: 6px; max-width: 640px; margin-top: 8px; }
.nr2020-container .nr-field input[type="number"] { max-width: 160px; }

.nr2020-container .nr-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin: 6px 0 16px; }
.nr2020-container .nr-btn { font: inherit; font-weight: 700; font-size: 1.05rem; color: #fffdf8; background-color: #1b2d52; border: 0; border-radius: 4px; padding: 12px 26px; min-height: 48px; cursor: pointer; letter-spacing: 0.02em; }
.nr2020-container .nr-btn:hover { background-color: #14203a; color: #fffdf8; }
.nr2020-container .nr-btn:disabled { background-color: #48536a; color: #ffffff; cursor: not-allowed; }
.nr2020-container .nr-err { color: #8f1f24; font-weight: 600; min-height: 1.2em; }

.nr2020-container .nr-last { background-color: #fffdf8; color: #14203a; border: 1px solid #d6cfbf; border-top: 4px solid #1b2d52; border-radius: 4px; padding: 16px 20px; margin-bottom: 16px; }
.nr2020-container .nr-last-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.nr2020-container .nr-last-k { font-size: 0.78rem; letter-spacing: 0.14em; text-transform: uppercase; color: #7c5410; font-weight: 700; }
.nr2020-container .nr-dash { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 16px; margin: 10px 0; }
.nr2020-container .nr-dash-card { padding: 12px 14px; border: 1px solid #d6cfbf; border-radius: 4px; background-color: #f5f2ea; color: #14203a; }
.nr2020-container .nr-dash-card.is-behind { background-color: #1b2d52; color: #f5f2ea; border-color: #1b2d52; }
.nr2020-container .nr-dash-card .nr-dash-k { font-size: 0.75rem; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 700; }
.nr2020-container .nr-dash-card .nr-dash-v { display: block; font-family: Georgia, serif; font-size: 2rem; font-weight: 700; line-height: 1.15; }
.nr2020-container .nr-dash-card.is-behind .nr-dash-v { color: #e6c27a; background-color: #1b2d52; }
.nr2020-container .nr-events { margin: 8px 0 0; padding-left: 20px; display: grid; gap: 4px; }
.nr2020-container .nr-events li.nr-ev-good::marker { color: #24603a; }
.nr2020-container .nr-events li.nr-ev-bad::marker { color: #8f1f24; }
.nr2020-container .nr-seals { margin: 10px 0 0; padding: 10px 12px; background-color: #f4ead6; color: #14203a; border-radius: 4px; font-size: 0.95rem; }

.nr2020-container .nr-mirror { background-color: #fffdf8; color: #14203a; border: 1px solid #d6cfbf; border-top: 6px double #1b2d52; border-radius: 4px; padding: 22px 26px; margin-bottom: 16px; display: grid; gap: 16px; }
.nr2020-container .nr-mir-top { display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap; }
.nr2020-container .nr-mir-score { font-family: Georgia, serif; font-size: 3.6rem; font-weight: 700; color: #1b2d52; line-height: 1; }
.nr2020-container .nr-mir-max { font-size: 1.2rem; color: #48536a; }
.nr2020-container .nr-mir-verdict { font-family: Georgia, serif; font-style: italic; font-size: 1.5rem; color: #7c5410; }
.nr2020-container .nr-mir-sub { display: flex; gap: 18px; flex-wrap: wrap; font-size: 0.95rem; color: #48536a; }
.nr2020-container .nr-mirror h3 { font-family: Georgia, serif; font-size: 1.15rem; color: #1b2d52; margin-bottom: 6px; }
.nr2020-container .nr-mirror ul, .nr2020-container .nr-mirror ol { margin: 0; padding-left: 20px; display: grid; gap: 6px; }
.nr2020-container .nr-turn { background-color: #f7e3e2; color: #14203a; border-left: 4px solid #8f1f24; padding: 12px 16px; border-radius: 4px; }
.nr2020-container .nr-turn.is-clean { background-color: #e2f0e6; border-left-color: #24603a; }
.nr2020-container .nr-lo-row { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 8px; align-items: start; }
.nr2020-container .nr-lo-mark { font-weight: 700; font-family: Georgia, serif; }
.nr2020-container .nr-lo-mark.is-met { color: #24603a; }
.nr2020-container .nr-lo-mark.is-part { color: #7c5410; }
.nr2020-container .nr-lo-mark.is-miss { color: #8f1f24; }
.nr2020-container .nr-chart { width: 100%; max-width: 560px; height: auto; display: block; }
.nr2020-container .nr-chart .nr-c-axis { stroke: #8d8574; stroke-width: 1; }
.nr2020-container .nr-chart .nr-c-grid { stroke: #e3ddcf; stroke-width: 1; }
.nr2020-container .nr-chart .nr-c-e { stroke: #7c5410; stroke-width: 3; fill: none; }
.nr2020-container .nr-chart .nr-c-s { stroke: #1b2d52; stroke-width: 3; fill: none; stroke-dasharray: 6 4; }
.nr2020-container .nr-chart text { font-size: 12px; fill: #48536a; font-family: -apple-system, Segoe UI, Arial, sans-serif; }
.nr2020-container .nr-table-wrap { overflow-x: auto; }
.nr2020-container .nr-table { border-collapse: collapse; width: 100%; font-size: 0.92rem; font-variant-numeric: tabular-nums; }
.nr2020-container .nr-table th, .nr2020-container .nr-table td { border-bottom: 1px solid #d6cfbf; padding: 6px 8px; text-align: left; }
.nr2020-container .nr-table th { color: #48536a; font-weight: 600; }
.nr2020-container .nr-history { background-color: #f5f2ea; color: #14203a; border-top: 1px solid #d6cfbf; padding: 8px 2px; }
.nr2020-container .nr-history summary { cursor: pointer; font-weight: 600; color: #1b2d52; min-height: 32px; display: flex; align-items: center; }

@media (max-width: 960px) {
  .nr2020-container .nr-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .nr2020-container .nr-kpi { border-bottom: 1px solid #d6cfbf; }
  .nr2020-container .nr-dial-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .nr2020-container .nr-signals-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .nr2020-container { padding: 16px 16px 24px; }
  .nr2020-container .nr-title { font-size: 1.8rem; }
  .nr2020-container .nr-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .nr2020-container .nr-opts, .nr2020-container .nr-checks, .nr2020-container .nr-dial-grid, .nr2020-container .nr-voices, .nr2020-container .nr-dash { grid-template-columns: 1fr; }
  .nr2020-container .nr-rail { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .nr2020-container .nr-memo { padding: 16px; }
  .nr2020-container .nr-alloc-row { grid-template-columns: minmax(0, 1fr) 84px; }
  .nr2020-container .nr-counter { align-items: flex-start; }
}
@media (prefers-reduced-motion: reduce) {
  .nr2020-container *, .nr2020-container *::before, .nr2020-container *::after { transition: none !important; animation: none !important; }
}

