            var r = function() { h ^= h << 13; h >>>= 0; h ^= h >>> 17; h ^= h << 5; h >>>= 0; return (h % 10000) / 10000; };
            return { hf: 0.9 + 0.2 * r(), xf: 0.9 + 0.2 * r(), bf: 0.9 + 0.2 * r() };
        }

        _design(d) {
            var mit = C.MIT[d.train] || 0;
            var objW = d.vis > 0 ? 1 : 0.2;
            var cost = C.CR[d.rec] + C.CV[d.vis] + C.CO[d.obj] * objW + C.CW[d.wt] + C.CI[d.info];
            var gain = C.GT[d.train] + (d.wt === 1 ? 3 : 0) + ((d.info === 1 || d.info === 2) ? 2 : 0) + (d.consent === 'yes' ? 1 : 0);
            var ben = C.BR[d.rec] + C.BW[d.wt] + C.BI[d.info] + C.BV[d.vis] * (1 - d.obj / 4) + C.BT[d.train] - (d.vis > 0 ? 10 * d.obj / 4 : 0);
            return { cost: cost * (1 - mit), gain: gain, ben: ben, mit: mit, cov: C.SCOPE_N[d.scope] / C.STAFF };
        }

        _spend(d) {
            return C.REC_C[d.rec] + C.VIS_C[d.vis] + C.WT_C[d.wt] + C.INFO_C[d.info] + C.SCOPE_N[d.scope] * (C.TRAIN_C[d.train] || 0) + (d.consent === 'yes' ? C.CONSENT_C : 0);
        }

        _hiding(d, cov, sf, vol) {
            var z = this._design(d);
