            var x = clamp(100 - X / 2.5, 0, 100);
            var f = clamp(F, 0, 100);
            return { o: C.W.E * e + C.W.S * s + C.W.A * a + C.W.X * x + C.W.F * f, e: e, s: s, a: a, x: x, f: f };
        }

        _norm(dec) {
            var r1 = dec.r1 || FOUNDER.r1;
            var r2 = dec.r2 || null;
            var r3 = dec.r3 || null;
            var r4 = dec.r4 || null;
            var out = { r1: { alloc: { talent: Number(r1.talent) || 0, courage: Number(r1.courage) || 0, climate: Number(r1.climate) || 0, route: Number(r1.route) || 0 }, metric: r1.metric || 'volume' } };
            if (r2) out.r2 = { rec: r2.rec, vis: r2.vis, obj: r2.obj, wt: r2.wt, info: r2.info, scope: r2.scope, train: r2.train || 'basic', consent: r2.consent || 'no', pred: Number(r2.pred) || 0 };
            if (r3 && out.r2) out.r3 = { d: { rec: r3.rec, vis: r3.vis, obj: r3.obj, wt: r3.wt, info: r3.info, scope: r3.scope, train: out.r2.train, consent: out.r2.consent }, dispute: r3.dispute || 'keep', carrier: r3.carrier || 'defend', pred: Number(r3.pred) || 0 };
            if (r4 && out.r3) {
                var z = {};
                ZONES.forEach(function(k) { z[k] = !!(r4.zones && r4.zones[k]); });
                out.r4 = { rec: r4.reco || 'scale', zones: z, gov: r4.gov || 'founder', hire: r4.hire || 'resign', stop: Number(r4.stop) || 0, pred: Number(r4.pred) || 0 };
