        }

        _run(decRaw, upto, seed) {
            var self = this;
            var dec = this._norm(decRaw || {});
            var sf = this._sf(seed);
            var out = { rounds: [], sf: sf };
            var al = dec.r1.alloc;
            var dist = Math.abs(al.talent - C.TRUTH.talent) + Math.abs(al.courage - C.TRUTH.courage) + Math.abs(al.climate - C.TRUTH.climate) + Math.abs(al.route - C.TRUTH.route);
            var D = clamp(100 - dist / 2, 0, 100);
            var focus = (al.climate + al.route) / 100;
            var eff = 0.45 + 0.55 * focus;
            var vol = dec.r1.metric === 'volume';
            if (vol) eff *= 0.72;
            var MET = { volume: 0, ttsurface: 100, dissent: 85, engagement: 35 }[dec.r1.metric] || 0;
            var F1 = C.F0 - 14 * clamp((70 - al.courage) / 60, 0, 1) + (vol ? 3 : 0);
            var o1 = this._outcome(C.E0, C.S0, C.A0, 0, F1);
            out.D = D; out.MET = MET; out.eff = eff; out.vol = vol; out.metric = dec.r1.metric; out.dec = dec;
            out.rounds.push({ t: 1, E: C.E0, S: C.S0, A: C.A0, X: 0, F: F1, H: 0, B: 0, score: Math.round(o1.o), o: o1, P: 0, dash: this._dash(dec.r1.metric, C.E0, C.S0, null, 0, 1) });
            if (upto < 2 || !dec.r2) return out;
            var d2 = dec.r2;
            var z2 = this._design(d2);
            var dev2 = DIALS.reduce(function(s, k) { return s + (4 - d2[k]); }, 0) / 24;
            var F2 = clamp(F1 - 30 * dev2 + (vol ? 5 : 0) + (d2.consent === 'yes' ? -2 : 0), 0, 100);
            var H2 = 0.3 * this._hiding(d2, z2.cov, sf, vol);
            var nov = z2.cov * 7 * (d2.rec + d2.vis) / 8;
            var E2 = clamp(C.E0 + z2.cov * z2.ben * eff * 0.5 + nov - 0.7 * H2, 5, 80);
            var o2 = this._outcome(E2, C.S0, C.A0, 0, F2);
            out.dev2 = dev2;
            out.spend2 = this._spend(d2);
            out.sig = { dm: Math.round(2 * this._hiding(d2, z2.cov, sf, vol)), gap: d2.vis ? this._bias(d2, sf) : C.B0 * sf.bf, xp: C.XP[d2.rec] * sf.xf * (d2.consent === 'yes' ? 0.25 : 1), cov: z2.cov };
            out.rounds.push({ t: 2, E: E2, S: C.S0, A: C.A0, X: 0, F: F2, H: H2, B: 0, score: Math.round(o2.o), o: o2, P: 0, cov: z2.cov, dash: this._dash(dec.r1.metric, E2, C.S0, d2, z2.cov, 2) });
            if (upto < 3 || !dec.r3) return out;
            var r3 = dec.r3;
            var d3 = r3.d;
            var z3 = this._design(d3);
            out.spend3 = out.spend2 + Math.max(0, this._spend(d3) - out.spend2) + (r3.dispute === 'audit' ? C.AUDIT_C : 0) + (r3.carrier === 'settle' ? C.SETTLE_C : 0);
            var Hd = function(d) { return self._hiding(d, self._design(d).cov, sf, vol); };
            var H3 = 0.5 * Hd(d2) + 0.5 * Hd(d3);
            var Bm = { audit: 0.35, anon: 1.3, keep: 1, suspend: 0 }[r3.dispute];
            var B3 = this._bias(d3, sf) * Bm;
            var d3e = Object.assign({}, d3, { vis: r3.dispute === 'suspend' ? 0 : d3.vis });
            var z3e = this._design(d3e);
            var Sd = function(z, d, Bx) { return z.cov * C.KS * (z.gain - z.cost) - C.FS[d.scope] * (d.train === 'none' ? 1.3 : 1) - 6 * Bx * (0.3 + 0.7 * d.vis / 4) * z.cov; };
            var Ad = function(z, d, Bx) { return z.cov * C.KA * Math.max(0, z.cost - z.gain) + C.FA[d.scope] + 1.5 * Bx * z.cov + (d.wt >= 3 ? 1.5 * z.cov : 0); };
            var dS3 = { suspend: -9, keep: -3, anon: -2, audit: 2 }[r3.dispute] + { defend: -3, settle: -2, stopext: 0, publish: 2 }[r3.carrier] + (d2.consent === 'yes' ? 1.5 : -1.5);
            var S3 = clamp(C.S0 + 0.5 * Sd(z2, d2, this._bias(d2, sf)) + 0.5 * Sd(z3e, d3e, B3) + dS3, 15, 85);
            var chill = { suspend: 0.75, keep: 0.9, anon: 0.95, audit: 1 }[r3.dispute];
            var E3raw = C.E0 + (0.5 * z2.cov * z2.ben + 0.5 * z3e.cov * z3e.ben * chill) * eff;
            var E3 = clamp(E3raw - 0.7 * H3, 5, 80);
            var A3 = clamp(C.A0 + 0.5 * Ad(z2, d2, this._bias(d2, sf)) + 0.5 * Ad(z3e, d3e, B3) + (r3.dispute === 'suspend' ? 0.5 : 0) - 0.04 * (E3 - C.E0), 6, 35);
            var xPart = function(d) { return C.XP[d.rec] * sf.xf * (d.consent === 'yes' ? 0.25 : 1); };
            var cm = { defend: 1.6, settle: 0.9, stopext: 0.5, publish: 0.35 }[r3.carrier];
            var X3 = Math.max(xPart(d2), xPart(d3)) * cm + (d3.info === 4 ? 20 * z3.cov : 0) + 120 * B3 * (d3.vis >= 3 ? 1 : 0.3) * z3.cov + (r3.carrier === 'settle' ? C.SETTLE_C : 0);
            var dev3 = DIALS.reduce(function(s, k) { return s + (4 - d3[k]); }, 0) / 24;
            var F3 = clamp(F1 - 30 * dev3 + (vol ? 5 : 0) + (d2.consent === 'yes' ? -2 : 0) + 0.8 * (E3 - C.E0) + { suspend: -10, keep: 4, anon: -2, audit: -3 }[r3.dispute] + { defend: 3, settle: 0, stopext: -2, publish: -3 }[r3.carrier], 0, 100);
            var o3 = this._outcome(E3, S3, A3, X3, F3);
            var cal = [Math.min(1, Math.abs(d2.pred - S3) / 15)];
            var P3 = 0.4 * D + 0.25 * MET + 0.35 * 100 * (1 - cal[0]);
            var sc3 = clamp(Math.round(0.75 * o3.o + 0.25 * P3), 0, 100);
            out.rounds.push({ t: 3, E: E3, S: S3, A: A3, X: X3, F: F3, H: H3, B: B3, score: sc3, o: o3, P: P3, cov: z3.cov, dash: this._dash(dec.r1.metric, E3, S3, d3, z3.cov, 3) });
            if (upto < 4 || !dec.r4) return out;
            var r4 = dec.r4;
            var healthy = (S3 >= C.S0 - 1) && (H3 < 8) && (B3 < 0.3);
            var cov3 = z3.cov;
            var C12 = { scale: 1, adapt: Math.max(cov3, 0.7), hold: cov3, stop: 0 }[r4.rec];
            var zones = r4.zones;
            var good = GOODZ.filter(function(k) { return zones[k]; }).length;
            var trap = !!zones.zGo;
            var d4 = Object.assign({}, d3e, { scope: d3.scope });
            var z4 = this._design(d4);
            z4.cov = C12;
            if (trap) z4.ben -= C.BR[d4.rec] * 0.7;
            if (trap && d4.wt === 1) z4.ben -= C.BW[1] * 0.7;
            var B4 = B3 * { panel: 0.5, people: 0.8, founder: 1.2, vendor: 0.9 }[r4.gov];
            var H4 = this._hiding(d4, C12, sf, vol) * (1 - 0.12 * good * (d4.rec >= 2 ? 1 : 0.5));
            if (r4.rec === 'scale') H4 += 12 * Math.max(0, C12 - 0.7);
            var fiatS = 0;
            var fiatA = 0;
            if (r4.rec === 'scale') { fiatS = C.FS[4] + (d3.scope < 4 ? 5 : 0); fiatA = C.FA[4]; }
            var keepFiat = (r4.rec === 'adapt' || r4.rec === 'hold') ? C.FS[d3.scope] : 0;
            var dzS = z4.cov * C.KS * (z4.gain - z4.cost) - keepFiat - fiatS - 6 * B4 * (d4.vis / 4) * C12 + 2.5 * good * (0.5 + d4.rec / 4) - (trap ? 2 : 0);
            var govS = { panel: 2, people: 0, founder: -2, vendor: -1 }[r4.gov];
            var hireS = { none: 0, disclose: 2, screen: -1, resign: -5 }[r4.hire];
            var hireA = { none: 0, disclose: -1.2, screen: 0.8, resign: 5 }[r4.hire];
            var stopS = r4.rec === 'stop' ? -3 : r4.rec === 'hold' ? 2 : 0;
            var carS = { defend: -3, settle: -1.5, stopext: 0, publish: 1.5 }[r3.carrier] + (d2.consent === 'yes' ? 1.5 : -1.5);
            var S4 = clamp(C.S0 + 0.3 * (S3 - C.S0) + 0.7 * dzS + govS + hireS + stopS + carS, 15, 85);
            var covEff = Math.min(C12, 0.7) + 0.15 * Math.max(0, C12 - 0.7);
            var E4 = clamp(C.E0 + covEff * z4.ben * eff * chill + (r4.rec === 'stop' ? 2 : 0) - 0.7 * H4, 5, 80);
            var Ad4 = z4.cov * C.KA * Math.max(0, z4.cost - z4.gain) + (r4.rec === 'scale' ? fiatA : C.FA[d3.scope] * 0.5) + 1.5 * B4 * C12 + (d4.wt >= 3 ? 1.5 * C12 : 0);
            var A4 = clamp(C.A0 + 0.4 * (A3 - C.A0) + 0.6 * Ad4 + hireA - 0.25 * good - 0.04 * (E4 - C.E0), 6, 35);
            var xp = Math.max(xPart(d2), xPart(d3)) * cm * (zones.zExt ? 0.5 : 1) * (zones.zHr ? 0.8 : 1);
            var X4 = xp + (d3.info === 4 ? 20 * C12 * (zones.zPay ? 0.3 : 1) : 0) + 120 * B4 * (d4.vis >= 3 ? 1 : 0.3) * C12 + (r3.carrier === 'settle' ? C.SETTLE_C : 0);
            var F4 = clamp(F3 + { scale: 12, adapt: -4, hold: -8, stop: -25 }[r4.rec] + 0.8 * (E4 - E3) + { resign: 5, screen: 2, disclose: -2, none: -3 }[r4.hire] + { founder: 4, people: 0, panel: -2, vendor: 0 }[r4.gov] - good, 0, 100);
            var rolled = r4.rec !== 'stop' && r4.stop > 0 && S4 < r4.stop;
            if (rolled) { S4 = Math.max(S4, C.S0 - 2); E4 = C.E0 + 1; A4 = Math.min(A4, Math.max(C.A0, A3)); F4 = clamp(F4 - 10, 0, 100); }
            var o4 = this._outcome(E4, S4, A4, X4, F4);
            cal.push(Math.min(1, Math.abs(r3.pred - this._of14(E4)) / 4));
            cal.push(Math.min(1, Math.abs(r4.pred - A4) / 8));
            var calS = 100 * (1 - (cal[0] + cal[1] + cal[2]) / 3);
            var zq = clamp(good / 5 * 100 - (trap ? 50 : 0), 0, 100);
            var gq = { panel: 100, people: 60, vendor: 40, founder: 0 }[r4.gov];
            var rq = healthy ? { adapt: 100, hold: 70, scale: 10, stop: 0 }[r4.rec] : { hold: 100, adapt: 40, stop: 30, scale: 0 }[r4.rec];
            var stv = r4.stop;
            var sq = stv <= 0 ? 0 : (stv >= 42 && stv <= 48) ? 100 : stv < 42 ? clamp((stv - 30) / 12 * 100, 0, 100) : clamp((60 - stv) / 12 * 100, 0, 100);
            var gov = 0.4 * zq + 0.2 * gq + 0.25 * rq + 0.15 * sq;
            var P4 = 0.25 * D + 0.15 * MET + 0.25 * calS + 0.35 * gov;
            var sc4 = clamp(Math.round(0.7 * o4.o + 0.3 * P4), 0, 100);
            out.rolled = rolled; out.healthy = healthy; out.good = good; out.trap = trap; out.C12 = C12; out.calS = calS; out.cal = cal;
            out.q = { zq: zq, gq: gq, rq: rq, sq: sq };
            out.rounds.push({ t: 4, E: E4, S: S4, A: A4, X: X4, F: F4, H: H4, B: B4, score: sc4, o: o4, P: P4, cov: C12, dash: this._dash(dec.r1.metric, E4, S4, d4, C12, 4) });
            return out;
        }

        _dash(metric, E, S, d, cov, t) {
            if (metric === 'volume') {
                var v = 3;
                if (d) v = 3 + (t >= 3 ? 34 : 30) * cov * (d.rec + d.vis) / 8;
                return { k: 'volume', v: Math.round(v) };
            }
            if (metric === 'ttsurface') return { k: 'ttsurface', v: Math.round(41 * Math.pow(14 / Math.max(5, E), 0.9)) };
            if (metric === 'dissent') return { k: 'dissent', v: Math.round(clamp(6 + 1.1 * (E - 14) + (d && d.wt === 1 ? 14 * cov : 0), 0, 95)) };
            return { k: 'engagement', v: Math.round(62 + (t >= 3 ? 0.6 * (S - 49) : 0)) };
        }

        _of14(E) {
            return clamp(Math.round(E / 100 * 14), 0, 14);
        }

        _composite(r) {
            return Math.max(0, Math.min(100, Math.round(r && typeof r.score === 'number' ? r.score : 0)));
        }

        _tier(score) {
            var s = Math.round(score);
            if (s >= C.T_EXC) return 'excellent';
            if (s >= C.T_GOOD) return 'good';
            if (s >= C.T_DEV) return 'developing';
            return 'beginner';
        }

        _round(state) {
            var p = parseInt(state.currentPeriod, 10);
            if (!isFinite(p) || p < 1) p = 1;
            return Math.min(C.ROUNDS, p);
        }

        _played(state) {
            var ds = state.domainState || {};
            if (ds.finished) return C.ROUNDS;
            var n = parseInt(ds.played, 10);
            return isFinite(n) ? Math.max(0, Math.min(C.ROUNDS, n)) : 0;
        }

        _showRound(state) {
            var ds = state.domainState || {};
            if (ds.finished) return ROUNDS.length;
            return Math.min(ROUNDS.length, this._played(state) + 1);
        }

        _designOf(dec, t) {
            var n = this._norm(dec);
            if (t >= 3 && n.r3) return n.r3.d;
            if (t >= 2 && n.r2) return n.r2;
            return null;
        }

        /* ---------------- reading and checking ---------------- */

        _radio(name) {
            var vals = OPT[name] || [];
            for (var i = 0; i < vals.length; i++) {
                var el = document.getElementById(name + '_' + vals[i]);
                if (el && el.checked) return vals[i];
            }
            return null;
        }

        _setRadio(name, v) {
            (OPT[name] || []).forEach(function(x) {
                var el = document.getElementById(name + '_' + x);
                if (el) el.checked = (x === v);
            });
        }

        _numVal(id) {
            var el = document.getElementById(id);
            var raw = el ? String(el.value).trim().replace(',', '.') : '';
            return raw === '' ? NaN : Number(raw);
        }

        _setVal(id, v) {
            var el = document.getElementById(id);
            if (el) el.value = String(v);
        }

        _readDials() {
            var self = this;
            var o = {};
            DIALS.forEach(function(k) {
                var v = self._numVal('d' + DIAL_ID[k]);
                o[k] = isFinite(v) ? clamp(Math.round(v), 0, 4) : 4;
            });
            return o;
        }

        _readRound(t) {
            var v = {};
            if (t === 1) {
                v.talent = this._numVal('aTalent');
                v.courage = this._numVal('aCourage');
                v.climate = this._numVal('aClimate');
                v.route = this._numVal('aRoute');
                v.metric = this._radio('nrMetric');
            }
            if (t === 2 || t === 3) Object.assign(v, this._readDials());
            if (t === 2) {
                v.train = this._radio('nrTrain');
                v.consent = this._radio('nrConsent');
                v.pred = this._numVal('nrPred2');
            }
            if (t === 3) {
                v.dispute = this._radio('nrDispute');
                v.carrier = this._radio('nrCarrier');
                v.pred = this._numVal('nrPred3');
            }
            if (t === 4) {
                v.reco = this._radio('nrRec');
                v.gov = this._radio('nrGov');
                v.hire = this._radio('nrHire');
                v.stop = this._numVal('nrStop');
                v.pred = this._numVal('nrPred4');
                v.zones = {};
                ZONES.forEach(function(k) { var el = document.getElementById(k); v.zones[k] = !!(el && el.checked); });
            }
            var note = document.getElementById('nrNote');
            v.note = note ? String(note.value || '').slice(0, 600) : '';
            return v;
        }

        _liveSpend(t, v, dec) {
            var n = this._norm(dec);
            if (t === 2) {
                return this._spend({ rec: v.rec, vis: v.vis, obj: v.obj, wt: v.wt, info: v.info, scope: v.scope, train: v.train || 'none', consent: v.consent || 'no' });
            }
            if (t === 3 && n.r2) {
                var s2 = this._spend(n.r2);
                var s3 = this._spend({ rec: v.rec, vis: v.vis, obj: v.obj, wt: v.wt, info: v.info, scope: v.scope, train: n.r2.train, consent: n.r2.consent });
                return s2 + Math.max(0, s3 - s2) + (v.dispute === 'audit' ? C.AUDIT_C : 0) + (v.carrier === 'settle' ? C.SETTLE_C : 0);
            }
            return 0;
        }

        _check(t, v, dec) {
            var self = this;
            var badInt = function(x, lo, hi, step) { return !isFinite(x) || x < lo || x > hi || Math.abs(Math.round(x / step) * step - x) > 1e-9; };
            if (t === 1) {
                var keys = ['talent', 'courage', 'climate', 'route'];
                for (var i = 0; i < keys.length; i++) {
                    if (badInt(v[keys[i]], 0, 100, 5)) return this._t('err_alloc_n');
                }
                var sum = keys.reduce(function(s, k) { return s + v[k]; }, 0);
                if (sum !== 100) return this._t('err_alloc_sum', { n: sum });
                if (!v.metric) return this._t('err_pick', { what: this._t('metric_legend') });
            }
            if (t === 2) {
                if (!v.train) return this._t('err_pick', { what: this._t('train_legend') });
                if (!v.consent) return this._t('err_pick', { what: this._t('consent_legend') });
                if (badInt(v.pred, 0, 100, 1)) return this._t('err_pred', { lo: 0, hi: 100 });
            }
            if (t === 3) {
                if (!v.dispute) return this._t('err_pick', { what: this._t('dispute_legend') });
                if (!v.carrier) return this._t('err_pick', { what: this._t('carrier_legend') });
                if (badInt(v.pred, 0, 14, 1)) return this._t('err_pred', { lo: 0, hi: 14 });
            }
            if (t === 2 || t === 3) {
                var sp = this._liveSpend(t, v, dec);
                if (sp > C.BUDGET + 1e-6) return this._t('err_budget', { s: self._money(sp * 1000), b: self._money(C.BUDGET * 1000) });
            }
            if (t === 4) {
                if (!v.reco) return this._t('err_pick', { what: this._t('rec_legend') });
                if (!v.gov) return this._t('err_pick', { what: this._t('gov_legend') });
                if (!v.hire) return this._t('err_pick', { what: this._t('hire_legend') });
                if (badInt(v.stop, 0, 100, 1)) return this._t('err_stop');
                if (badInt(v.pred, 0, 40, 0.5)) return this._t('err_pred', { lo: 0, hi: 40 });
            }
            return null;
        }

        _showErr(text) {
            var err = document.getElementById('nrErr');
            if (err) err.textContent = text || '';
            if (text) {
                var sim = window.mySimulation;
                if (sim && sim.uiManager && typeof sim.uiManager.showNotification === 'function') sim.uiManager.showNotification(text, 'warning');
            }
        }

        /* ---------------- events and drafts ---------------- */

        _bindOnce() {
            if (this._bound) return;
            var root = document.getElementById('nr2020');
            if (!root) return;
            this._bound = true;
            var self = this;
            var onEdit = function() {
                self._saveDraft();
                self._paintLive();
            };
            root.addEventListener('input', onEdit);
            root.addEventListener('change', onEdit);
            var repaint = function() { self._safeRender(); };
            var reload = function() { self._shown = null; self._safeRender(); };
            document.addEventListener('express:langchanged', repaint);
            document.addEventListener('language:changed', repaint);
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                sim.eventBus.on('language:changed', repaint);
                sim.eventBus.on('framework:initialized', repaint);
                sim.eventBus.on('state:loaded', reload);
                sim.eventBus.on('period:submitted', repaint);
                sim.eventBus.on('period:undone', reload);
            }
        }

        _safeRender() {
            try { this.render(); } catch (err) { return null; }
            return true;
        }

        _saveDraft() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var st = sim.state;
            if ((st.domainState || {}).finished) return;
            var t = this._showRound(st);
            var dec = st.decisions || {};
            dec.draft = { round: t, v: this._readRound(t) };
            st.decisions = dec;
        }

        /* ---------------- render ---------------- */

        render() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var st = sim.state;
            var ds = st.domainState || {};
            var dec = st.decisions || {};
            var finished = !!ds.finished;
            var played = this._played(st);
            var t = this._showRound(st);
            var m = this._run(dec, Math.max(1, played), this._seedOf(st));
            var html = document.documentElement;
            if (html) html.setAttribute('lang', this._lang());
            this._paintHead(t, finished, played);
            this._paintObjectives(t, finished);
            this._paintFourteen(m, played);
            this._paintKpis(m, played);
            this._paintStory();
            this._paintLast(dec, m, played);
            var decide = document.getElementById('nrDecide');
            var mirror = document.getElementById('nrMirror');
            var brief = document.getElementById('nrBrief');
            if (finished) {
                if (decide) decide.hidden = true;
                if (brief) brief.hidden = true;
                if (mirror) { mirror.hidden = false; mirror.innerHTML = this._mirrorHTML(dec, m); }
                return;
            }
            if (decide) decide.hidden = false;
            if (brief) brief.hidden = false;
            if (mirror) { mirror.hidden = true; mirror.innerHTML = ''; }
            this._paintBrief(t, m);
            this._paintBoxes(t, m, dec);
            if (this._shown !== t) {
                this._syncControlsFromDecisions(dec, t);
                this._shown = t;
            }
            this._paintLive();
            var bt = document.getElementById('nrBtnText');
            if (bt) bt.textContent = this._t('btn_r' + t);
        }

        _paintHead(t, finished, played) {
            var stg = document.getElementById('nrStage');
            if (stg) stg.textContent = finished ? this._t('stage_done') : this._t(ROUNDS[t - 1].stage);
            for (var i = 1; i <= C.ROUNDS; i++) {
                var li = document.getElementById('nrRail' + i);
                if (!li || !li.classList) continue;
                var done = finished || i <= played;
                li.classList.toggle('is-done', done);
                li.classList.toggle('is-now', !finished && i === t);
                if (!finished && i === t) li.setAttribute('aria-current', 'step'); else li.removeAttribute('aria-current');
            }
        }

        _paintObjectives(t, finished) {
            var now = document.getElementById('nrObjNow');
            var los = finished ? [] : ROUNDS[t - 1].lo;
            if (now) now.textContent = finished ? this._t('obj_done') : this._t(los.length > 1 ? 'obj_now' : 'obj_now1', { n: los.slice().sort().join(', ') });
            for (var i = 1; i <= 5; i++) {
                var li = document.getElementById('nrLo' + i);
                if (li && li.classList) li.classList.toggle('is-focus', los.indexOf(i) >= 0);
            }
            var box = document.getElementById('nrObj');
            if (box && !this._objClosed && t > 1) { box.open = false; this._objClosed = true; }
        }

        _personSVG(lit) {
            return '<svg class="nr-person' + (lit ? ' is-lit' : '') + '" viewBox="0 0 30 44" aria-hidden="true" focusable="false"><circle class="nr-p-head" cx="15" cy="9" r="6.5"/><path class="nr-p-body" d="M4 42 V27 a11 11 0 0 1 22 0 V42 Z"/></svg>';
        }

        _paintFourteen(m, played) {
            var box = document.getElementById('nrFourteen');
            var cap = document.getElementById('nrFourteenCap');
            var r = m.rounds[m.rounds.length - 1];
            var k = played >= 2 ? this._of14(r.E) : 2;
            var html = '';
            for (var i = 0; i < 14; i++) html += this._personSVG(i < k);
            if (box) {
                box.innerHTML = html;
                box.setAttribute('aria-label', this._t('fourteen_aria', { k: k }));
            }
            if (cap) {
                var key = played < 2 ? 'fourteen_base' : (played >= C.ROUNDS ? 'fourteen_m12' : 'fourteen_now');
                cap.innerHTML = this._t(key, { k: '<strong>' + k + '</strong>', when: this._t('when_' + Math.max(1, played)) });
            }
        }

        _delta(cur, base, goodUp, fmt) {
            var dlt = cur - base;
            if (Math.abs(dlt) < 0.05) return this._t('d_same');
            var better = goodUp ? dlt > 0 : dlt < 0;
            var sign = dlt > 0 ? '+' : '−';
            return '<span class="' + (better ? 'nr-up' : 'nr-down') + '">' + sign + fmt(Math.abs(dlt)) + '</span> ' + this._t(better ? 'd_better' : 'd_worse');
        }

        _paintKpis(m, played) {
            var self = this;
            var r = played ? m.rounds[m.rounds.length - 1] : { E: C.E0, S: C.S0, A: C.A0, X: 0, F: C.F0 };
            var set = function(id, html) { var el = document.getElementById(id); if (el) el.innerHTML = html; };
            var i1 = function(x) { return self._num1(x); };
            set('nrKpiE', this._pct0(r.E));
            set('nrKpiEs', this._t('kpi_e_s', { k: this._of14(r.E) }) + ' · ' + this._delta(r.E, C.E0, true, function(x) { return self._num1(x) + ' ' + self._t('u_pts'); }));
            var sMeasured = played >= 3;
            set('nrKpiS', sMeasured ? String(Math.round(r.S)) : String(C.S0));
            set('nrKpiSs', sMeasured ? this._delta(r.S, C.S0, true, i1) : this._t('kpi_s_wait'));
            set('nrKpiA', this._num1(r.A) + (this._lang() === 'es' ? ' %' : '%'));
            set('nrKpiAs', played >= 3 ? this._delta(r.A, C.A0, false, i1) : this._t('kpi_a_wait'));
            set('nrKpiX', this._money(Math.round(r.X) * 1000));
            set('nrKpiXs', played >= 3 ? this._t('kpi_x_s') : this._t('kpi_x_wait'));
            set('nrKpiF', String(Math.round(r.F)));
            var bar = document.getElementById('nrKpiFbar');
            if (bar && bar.style) bar.style.width = Math.round(clamp(r.F, 0, 100)) + '%';
            set('nrKpiFs', this._t(r.F >= 70 ? 'kpi_f_hi' : r.F >= 45 ? 'kpi_f_mid' : 'kpi_f_lo'));
            var hist = ((window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {}).scoreHistory || [];
            if (played > 0 && hist.length) {
                var sc = Math.round(hist[hist.length - 1] || 0);
                set('nrKpiScore', String(sc));
                set('nrKpiScores', this._t('v_' + this._tier(sc)));
            } else {
                set('nrKpiScore', '—');
                set('nrKpiScores', this._t('kpi_score_none'));
            }
        }

        _paintStory() {
            var body = document.getElementById('nrStoryBody');
            if (!body) return;
            var self = this;
            var list = function(keys) { return '<ul>' + keys.map(function(k) { return '<li>' + self._t(k) + '</li>'; }).join('') + '</ul>'; };
            body.innerHTML = '<p>' + this._t('st_p1') + '</p><p>' + this._t('st_p2') + '</p><p><strong>' + this._t('st_mandate_t') + '</strong></p>'
                + list(['st_m1', 'st_m2', 'st_m3', 'st_m4'])
                + '<p><strong>' + this._t('st_rules_t') + '</strong></p>'
                + list(['st_r1', 'st_r2', 'st_r3', 'st_r4', 'st_r5'])
                + '<p>' + this._t('st_src') + '</p>';
        }

        _paintBrief(t, m) {
            var date = document.getElementById('nrBriefDate');
            var title = document.getElementById('nrBriefTitle');
            var body = document.getElementById('nrBriefBody');
            var voices = document.getElementById('nrVoices');
            if (date) date.textContent = this._t('date_r' + t);
            if (title) title.textContent = this._t('brief_t' + t);
            if (body) {
                var html = '<p>' + this._t('brief_r' + t) + '</p>';
                if (t === 2) html += '<p>' + this._t('brief_r2b') + '</p>';
                if (t === 3) html += '<p>' + this._t('brief_r3b') + '</p>';
                if (t === 4) html += '<p>' + this._t('brief_r4b') + '</p>';
                body.innerHTML = html;
            }
            if (voices) {
                voices.innerHTML = '<blockquote class="nr-voice"><p>' + this._t('vq_r' + t + 'a') + '</p><cite>' + this._t('vc_r' + t + 'a') + '</cite></blockquote>'
                    + '<blockquote class="nr-voice"><p>' + this._t('vq_r' + t + 'b') + '</p><cite>' + this._t('vc_r' + t + 'b') + '</cite></blockquote>';
            }
        }

        _paintBoxes(t, m, dec) {
            var show = function(id, on) { var el = document.getElementById(id); if (el) el.hidden = !on; };
            show('nrR1', t === 1);
            show('nrDials', t === 2 || t === 3);
            show('nrR2', t === 2);
            show('nrSignals', t === 3);
            show('nrR3', t === 3);
            show('nrR4', t === 4);
            show('nrForecast', t >= 2);
            show('nrPred2Box', t === 2);
            show('nrPred3Box', t === 3);
            show('nrPred4Box', t === 4);
            var help = document.getElementById('nrDialsHelp');
            if (help) help.textContent = this._t(t === 3 ? 'dials_help_r3' : 'dials_help_r2');
            var title = document.getElementById('nrDialsTitle');
            if (title) title.textContent = this._t(t === 3 ? 'dials_h_r3' : 'dials_h');
            if (t === 3) this._paintSignals(m);
        }

        _paintSignals(m) {
            var box = document.getElementById('nrSignals');
            if (!box || !m.sig) return;
            var sg = m.sig;
            box.innerHTML = '<h2 class="nr-h2">' + this._t('sig_h') + '</h2>'
                + '<div class="nr-signals-grid">'
                + '<div class="nr-signal"><b>+' + sg.dm + (this._lang() === 'es' ? ' %' : '%') + '</b><span>' + this._t('sig_dm') + '</span></div>'
                + '<div class="nr-signal"><b>−' + this._num1(sg.gap) + '</b><span>' + this._t('sig_gap') + '</span></div>'
                + '<div class="nr-signal"><b>' + this._money(Math.round(sg.xp) * 1000) + '</b><span>' + this._t('sig_x') + '</span></div>'
                + '</div>';
        }

        _syncControlsFromDecisions(dec, t) {
            var self = this;
            var draft = dec.draft;
            var saved = dec[ROUNDS[t - 1].key] || null;
            var v = (draft && draft.round === t && draft.v) ? draft.v : saved;
            if (t === 1) {
                var a = v || FOUNDER.r1;
                ['talent', 'courage', 'climate', 'route'].forEach(function(k) {
                    var id = 'a' + k.charAt(0).toUpperCase() + k.slice(1);
                    var x = a[k];
                    self._setVal(id, isFinite(x) ? x : FOUNDER.r1[k]);
                });
                this._setRadio('nrMetric', (v && v.metric) || null);
            }
            if (t === 2 || t === 3) {
                var base = v;
                if (!base && t === 3) base = dec.r2 || null;
                DIALS.forEach(function(k) {
                    var x = base && isFinite(base[k]) ? base[k] : FOUNDER.r2[k];
                    self._setVal('d' + DIAL_ID[k], x);
                });
            }
            if (t === 2) {
                this._setRadio('nrTrain', (v && v.train) || null);
                this._setRadio('nrConsent', (v && v.consent) || null);
                this._setVal('nrPred2', v && isFinite(v.pred) ? v.pred : C.S0);
            }
            if (t === 3) {
                this._setRadio('nrDispute', (v && v.dispute) || null);
                this._setRadio('nrCarrier', (v && v.carrier) || null);
                var sim = window.mySimulation;
                var m = this._run(dec, 2, this._seedOf(sim ? sim.state : null));
                this._setVal('nrPred3', v && isFinite(v.pred) ? v.pred : this._of14(m.rounds[m.rounds.length - 1].E));
            }
            if (t === 4) {
                this._setRadio('nrRec', (v && v.reco) || null);
                this._setRadio('nrGov', (v && v.gov) || null);
                this._setRadio('nrHire', (v && v.hire) || null);
                this._setVal('nrStop', v && isFinite(v.stop) ? v.stop : FOUNDER.r4.stop);
                ZONES.forEach(function(k) { var el = document.getElementById(k); if (el) el.checked = !!(v && v.zones && v.zones[k]); });
                var sim4 = window.mySimulation;
                var m4 = this._run(dec, 3, this._seedOf(sim4 ? sim4.state : null));
                var lastA = m4.rounds[m4.rounds.length - 1].A;
                this._setVal('nrPred4', v && isFinite(v.pred) ? v.pred : Math.round(lastA * 2) / 2);
            }
            var note = document.getElementById('nrNote');
            if (note) note.value = (v && v.note) || '';
            var err = document.getElementById('nrErr');
            if (err) err.textContent = '';
        }

        _paintLive() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var st = sim.state;
            if ((st.domainState || {}).finished) return;
            var self = this;
            var t = this._showRound(st);
            var dec = st.decisions || {};
            var v = this._readRound(t);
            if (t === 1) {
                var keys = ['talent', 'courage', 'climate', 'route'];
                var sum = 0;
                var segs = '';
                keys.forEach(function(k, i) {
                    var x = isFinite(v[k]) ? Math.max(0, v[k]) : 0;
                    sum += x;
                    segs += '<span class="nr-alloc-seg nr-seg-' + i + '" style="width:' + Math.min(100, x) + '%"></span>';
                });
                var bar = document.getElementById('nrAllocBar');
                if (bar) bar.innerHTML = segs;
                var tot = document.getElementById('nrAllocTotal');
                if (tot) {
                    tot.textContent = this._t(sum === 100 ? 'alloc_ok' : 'alloc_bad', { n: sum });
                    if (tot.classList) tot.classList.toggle('is-bad', sum !== 100);
                }
            }
            if (t === 2 || t === 3) {
                var tv = t === 2 ? (v.train || 'none') : ((dec.r2 && dec.r2.train) || 'none');
                DIALS.forEach(function(k) {
                    var lvl = v[k];
                    var out = document.getElementById('o' + DIAL_ID[k]);
                    var txt = self._t('lv_' + k + '_' + lvl);
                    if (out) out.textContent = txt;
                    var inp = document.getElementById('d' + DIAL_ID[k]);
                    if (inp) inp.setAttribute('aria-valuetext', txt);
                    var cost = document.getElementById('c' + DIAL_ID[k]);
                    var c = k === 'scope' ? C.SCOPE_N[lvl] * (C.TRAIN_C[tv] || 0) : ({ rec: C.REC_C, vis: C.VIS_C, obj: C.OBJ_C, wt: C.WT_C, info: C.INFO_C }[k])[lvl];
                    var costKey = k === 'scope' ? 'dial_cost_scope' : 'dial_cost';
                    var mand = lvl === 4 ? ' · <span class="nr-mandate">' + self._t('dial_mandate') + '</span>' : '';
                    if (cost) cost.innerHTML = self._t(costKey, { c: self._money(c * 1000) }) + mand;
                    var card = inp ? inp.parentNode : null;
                    if (card && card.classList) card.classList.toggle('is-moved', lvl !== 4);
                });
                var sp = this._liveSpend(t, v, dec);
                var fill = document.getElementById('nrBudgetFill');
                if (fill && fill.style) fill.style.width = Math.round(clamp(sp / C.BUDGET, 0, 1) * 100) + '%';
                var bt = document.getElementById('nrBudget');
                if (bt) bt.textContent = this._t(sp > C.BUDGET ? 'budget_over' : 'budget_ok', { s: this._money(sp * 1000), b: this._money(C.BUDGET * 1000), l: this._money(Math.max(0, C.BUDGET - sp) * 1000) });
                var bbox = document.getElementById('nrBudgetBox');
                if (bbox && bbox.classList) bbox.classList.toggle('is-over', sp > C.BUDGET);
            }
            Object.keys(OPT).forEach(function(name) {
                OPT[name].forEach(function(x) {
                    var el = document.getElementById(name + '_' + x);
                    var lab = el ? el.parentNode : null;
                    if (lab && lab.classList) lab.classList.toggle('is-on', !!el.checked);
                });
            });
            ZONES.forEach(function(k) {
                var el = document.getElementById(k);
                var lab = el ? el.parentNode : null;
                if (lab && lab.classList) lab.classList.toggle('is-on', !!el.checked);
            });
        }

        _paintLast(dec, m, played) {
            var box = document.getElementById('nrLast');
            if (!box) return;
            if (!played) { box.hidden = true; box.innerHTML = ''; return; }
            box.hidden = false;
            var self = this;
            var r = m.rounds[played - 1];
            var html = '<div class="nr-last-head"><span class="nr-last-k">' + this._t('ro_k') + '</span><h2 class="nr-h2">' + this._t('ro_' + played) + '</h2></div>';
            var dk = r.dash.k;
            var dv = dk === 'ttsurface' ? this._t('dash_days', { n: r.dash.v }) : dk === 'dissent' ? this._pct0(r.dash.v) : String(r.dash.v);
            html += '<div class="nr-dash"><div class="nr-dash-card"><span class="nr-dash-k">' + this._t('dash_your') + '</span><span class="nr-dash-v">' + dv + '</span><span>' + this._t('dash_' + dk) + '</span></div>';
            if (played >= 3) {
                html += '<div class="nr-dash-card is-behind"><span class="nr-dash-k">' + this._t('dash_behind') + '</span><span class="nr-dash-v">' + this._t('dash_k14', { k: this._of14(r.E) }) + '</span><span>' + this._t('dash_behind_s', { p: Math.round(2 * r.H) }) + '</span></div>';
            } else {
                html += '<div class="nr-dash-card is-behind"><span class="nr-dash-k">' + this._t('dash_behind') + '</span><span class="nr-dash-v">?</span><span>' + this._t('dash_behind_wait') + '</span></div>';
            }
            html += '</div>';
            var evs = this._events(dec, m, played).map(function(e) { return '<li class="' + (e.g ? 'nr-ev-good' : 'nr-ev-bad') + '">' + e.s + '</li>'; });
            if (evs.length) html += '<ul class="nr-events">' + evs.join('') + '</ul>';
            if (played === 2 || played === 3) {
                var sim = window.mySimulation;
                var hint = sim ? this.getHint(sim.state, null) : null;
                if (hint) html += '<p class="nr-seals">' + hint + '</p>';
            }
            if (played === 3) {
                var n2 = m.dec.r2 || {};
                html += '<p class="nr-seals">' + this._t('seal_open2', { p: n2.pred, a: Math.round(r.S), d: Math.round(Math.abs(n2.pred - r.S)) }) + '</p>';
            }
            box.innerHTML = html;
            return self;
        }

        _events(dec, m, played) {
            var self = this;
            var n = m.dec;
            var r = m.rounds[played - 1];
            var out = [];
            var add = function(key, vars, good) { out.push({ s: self._t(key, vars), g: !!good }); };
            if (played === 1) {
                var c = n.r1.alloc.courage;
                if (c >= 50) add('ev1_wes_yes', {}, true); else add('ev1_wes_no', { n: Math.round(C.F0 - r.F) }, false);
                add('ev1_metric_' + n.r1.metric, {}, n.r1.metric !== 'volume');
            }
            if (played === 2) {
                var d2 = n.r2;
                add('ev2_live', { n: C.SCOPE_N[d2.scope] }, true);
                add('ev2_vol', { v: Math.round(3 + 30 * (C.SCOPE_N[d2.scope] / C.STAFF) * (d2.rec + d2.vis) / 8) }, true);
                if (d2.scope === 4) add('ev2_optout', { n: Math.round(37 * m.sf.hf) }, false);
                add(m.dev2 < 0.3 ? 'ev2_wes_happy' : 'ev2_wes_cold', {}, m.dev2 < 0.3);
                add('ev2_wait', {}, false);
            }
            if (played === 3) {
                var quits = Math.round(r.A / 100 * C.STAFF * 10 / 52);
                var base = Math.round(C.A0 / 100 * C.STAFF * 10 / 52);
                add('ev3_pulse', { s: Math.round(r.S) }, r.S >= C.S0);
                add(r.H >= 3 ? 'ev3_dm_up' : 'ev3_dm_flat', { p: Math.round(2 * r.H) }, r.H < 3);
                add('ev3_quits', { n: quits, b: base, c: this._money(Math.max(0, quits - base) * C.REPL * 1000) }, quits <= base);
                add('ev3_dp_' + n.r3.dispute, {}, n.r3.dispute === 'audit');
                add('ev3_ca_' + n.r3.carrier, { x: this._money(Math.round(r.X) * 1000) }, n.r3.carrier === 'publish' || n.r3.carrier === 'stopext');
            }
            if (played === 4) {
                add('ev4_' + n.r4.rec, { k: this._of14(r.E) }, n.r4.rec === (m.healthy ? 'adapt' : 'hold'));
                if (m.rolled) add('ev4_rollback', { s: n.r4.stop }, !m.healthy);
                if (m.trap) add('ev4_trap', {}, false);
                else if (m.good >= 4) add('ev4_zones_ok', { n: m.good }, true);
                else if (m.good === 0) add('ev4_zones_none', {}, false);
                else add('ev4_zones_few', { n: m.good }, false);
                add('ev4_hire_' + n.r4.hire, {}, n.r4.hire === 'disclose');
                add('ev4_gov_' + n.r4.gov, {}, n.r4.gov === 'panel');
            }
            return out;
        }

        /* ---------------- debrief ---------------- */

        _detect(m) {
            var n = m.dec;
            var al = n.r1.alloc;
            var d3 = n.r3 ? n.r3.d : {};
            return {
                courage: al.courage + al.talent >= 40,
                volume: n.r1.metric === 'volume',
                mandate: (m.dev2 || 0) < 0.25,
                traits: d3.vis >= 1 && d3.obj >= 3,
                believe: d3.wt >= 3,
                record: d3.rec >= 3 && (m.good || 0) < 3,
                suspend: n.r3 && n.r3.dispute === 'suspend',
                keep: n.r3 && n.r3.dispute === 'keep',
                anon: n.r3 && n.r3.dispute === 'anon',
                defend: n.r3 && n.r3.carrier === 'defend',
                scale: n.r4 && n.r4.rec === 'scale',
                stop: n.r4 && n.r4.rec === 'stop',
                holdHealthy: n.r4 && n.r4.rec === 'hold' && m.healthy,
                adaptSick: n.r4 && n.r4.rec === 'adapt' && !m.healthy,
                trap: !!m.trap,
                resign: n.r4 && n.r4.hire === 'resign',
                screen: n.r4 && n.r4.hire === 'screen',
                nostop: n.r4 && n.r4.stop <= 0,
                rollHigh: !!m.rolled && m.healthy,
                rollSaved: !!m.rolled && !m.healthy
            };
        }

        _insights(dec, m) {
            var d = this._detect(m);
            var r = m.rounds[m.rounds.length - 1];
            var out = [];
            var self = this;
            var add = function(k, v) { out.push(self._t(k, v || {})); };
            if (d.mandate) add('ins_mandate');
            if (d.courage) add('ins_courage', { c: m.dec.r1.alloc.courage + m.dec.r1.alloc.talent });
            if (d.volume) add('ins_volume');
            if (d.traits) add('ins_traits');
            if (d.believe) add('ins_believe');
            if (d.suspend) add('ins_suspend');
            if (d.scale) add('ins_scale');
            if (d.record) add('ins_record');
            if (d.trap) add('ins_trap');
            if (d.resign) add('ins_resign');
            if (d.keep) add('ins_keep');
            if (d.anon) add('ins_anon');
            if (d.defend) add('ins_defend');
            if (d.stop) add('ins_stop');
            if (d.holdHealthy) add('ins_hold');
            if (d.adaptSick) add('ins_adapt_sick');
            if (d.screen) add('ins_screen');
            if (d.nostop) add('ins_nostop');
            if (d.rollHigh) add('ins_roll_high', { s: m.dec.r4.stop });
            if (d.rollSaved) add('ins_roll_saved', { s: m.dec.r4.stop });
            if (out.length < 3 && !d.courage) add('ins_good_diag');
            if (out.length < 3 && !d.traits && !d.mandate) add('ins_good_proc');
            if (out.length < 3 && m.dec.r3 && m.dec.r3.d.scope <= 1) add('ins_good_pilot');
            if (out.length < 3 && m.dec.r3 && m.dec.r3.dispute === 'audit') add('ins_good_audit');
            if (out.length < 3 && m.good >= 4 && !m.trap) add('ins_good_zones');
            if (out.length < 3) add('ins_k14', { k: this._of14(r.E) });
            return out.slice(0, 5);
        }

        _withExpert(dec, field) {
            var x = JSON.parse(JSON.stringify(dec || {}));
            var parts = field.split('.');
            if (parts[0] === 'r1') {
                x.r1 = x.r1 || {};
                if (parts[1] === 'alloc') ['talent', 'courage', 'climate', 'route'].forEach(function(k) { x.r1[k] = EXPERT.r1[k]; });
                else x.r1.metric = EXPERT.r1.metric;
            } else if (parts[0] === 'design') {
                DIALS.forEach(function(k) {
                    if (x.r2) x.r2[k] = EXPERT.dials[k];
                    if (x.r3) x.r3[k] = EXPERT.dials[k];
                });
                if (x.r2) { x.r2.train = EXPERT.r2.train; x.r2.consent = EXPERT.r2.consent; }
            } else if (parts[0] === 'dial') {
                if (x.r2) x.r2[parts[1]] = EXPERT.dials[parts[1]];
                if (x.r3) x.r3[parts[1]] = EXPERT.dials[parts[1]];
            } else if (parts[0] === 'r2') {
                if (x.r2) x.r2[parts[1]] = EXPERT.r2[parts[1]];
            } else if (parts[0] === 'r3') {
                if (x.r3) x.r3[parts[1]] = EXPERT.r3[parts[1]];
            } else if (parts[0] === 'r4' && x.r4) {
                if (parts[1] === 'zones') { x.r4.zones = { z1on1: true, zHr: true, zDraft: true, zExt: true, zPay: true, zGo: false }; }
                else if (parts[1] === 'reco') x.r4.reco = parts[2];
                else x.r4[parts[1]] = EXPERT.r4[parts[1]];
            }
            return x;
        }

        _turningCandidates(m) {
            var c = ['r1.alloc', 'r1.metric', 'design.all'];
            DIALS.forEach(function(k) { c.push('dial.' + k); });
            c.push('r2.train', 'r2.consent', 'r3.dispute', 'r3.carrier', 'r4.zones', 'r4.gov', 'r4.hire', 'r4.stop');
            c.push('r4.reco.' + (m.healthy ? 'adapt' : 'hold'));
            return c;
        }

        _turning(dec, m) {
            var self = this;
            var seed = (window.mySimulation && window.mySimulation.state) ? this._seedOf(window.mySimulation.state) : 'ridgeline';
            var base = m.rounds[m.rounds.length - 1].score;
            var best = null;
            this._turningCandidates(m).forEach(function(f) {
                var alt = self._run(self._withExpert(dec, f), C.ROUNDS, seed);
                var s = alt.rounds[alt.rounds.length - 1].score;
                if (!best || s - base > best.gain) best = { f: f, gain: s - base, s: s };
            });
            if (!best || best.gain < 2) return this._t('turn_none');
            var key = best.f.split('.').slice(0, 2).join('_');
            return this._t('turn_fmt', { what: this._t('tp_' + key), s: best.s, b: base });
        }

        _chartSVG(m) {
            var rs = m.rounds;
            var W = 520;
            var H = 200;
            var L = 44;
            var R = 40;
            var T = 16;
            var B = 34;
            var x = function(i) { return L + (W - L - R) * i / 3; };
            var y = function(v) { return T + (H - T - B) * (1 - v / 80); };
            var grid = '';
            [0, 20, 40, 60, 80].forEach(function(g) { grid += '<line class="nr-c-grid" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(g) + '" y2="' + y(g) + '"/><text x="' + (L - 8) + '" y="' + (y(g) + 4) + '" text-anchor="end">' + g + '</text>'; });
            var pe = rs.map(function(r, i) { return x(i) + ',' + y(r.E); }).join(' ');
            var ps = rs.map(function(r, i) { return x(i) + ',' + y(i >= 2 ? r.S : 49); }).join(' ');
            var labels = '';
            for (var i = 0; i < rs.length; i++) labels += '<text x="' + x(i) + '" y="' + (H - 10) + '" text-anchor="middle">' + this._t('ax_' + (i + 1)) + '</text>';
            var aria = this._t('chart_aria', { e1: Math.round(rs[0].E), e4: Math.round(rs[rs.length - 1].E), s4: Math.round(rs[rs.length - 1].S) });
            return '<svg class="nr-chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + aria + '">' + grid
                + '<line class="nr-c-axis" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(0) + '" y2="' + y(0) + '"/>'
                + '<polyline class="nr-c-e" points="' + pe + '"/><polyline class="nr-c-s" points="' + ps + '"/>' + labels + '</svg>'
                + '<p class="nr-help">' + this._t('chart_legend') + '</p>';
        }

        _loStatus(m) {
            var n = m.dec;
            var d3 = n.r3.d;
            var r4 = n.r4;
            var lo = [];
            lo.push(m.D >= 80 ? 2 : m.D >= 55 ? 1 : 0);
            var proc = d3.obj <= 1 && d3.vis <= 2 && d3.wt <= 1 && d3.info >= 1 && d3.info <= 3;
            lo.push(proc ? 2 : (d3.obj <= 2 && d3.vis <= 3) ? 1 : 0);
            lo.push((m.good >= 4 && !m.trap && (d3.rec <= 3)) ? 2 : (m.good >= 2 && !m.trap) ? 1 : 0);
            var fair = (n.r3.dispute === 'audit' ? 1 : 0) + (r4.gov === 'panel' ? 1 : 0) + (d3.wt <= 1 ? 1 : 0);
            lo.push(fair === 3 ? 2 : fair >= 2 ? 1 : 0);
            var up = (r4.rec !== 'scale' && r4.rec !== 'stop') && r4.stop > 0;
            lo.push(up && m.q.rq >= 70 ? 2 : (r4.rec !== 'scale') ? 1 : 0);
            return lo;
        }

        _mirrorHTML(dec, m) {
            var self = this;
            var r = m.rounds[m.rounds.length - 1];
            if (!m.dec.r4) return '';
            var comp = this._composite(r);
            var tier = this._tier(comp);
            var ins = this._insights(dec, m).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var qs = ['q1', 'q2', 'q3'].map(function(k) { return '<li>' + self._t(k) + '</li>'; }).join('');
            var turn = this._turning(dec, m);
            var clean = turn === this._t('turn_none');
            var k14 = this._of14(r.E);
            var people = '';
            for (var i = 0; i < 14; i++) people += this._personSVG(i < k14);
            var seals = [
                this._t('seal_2', { p: m.dec.r2.pred, a: Math.round(m.rounds[2].S) }),
                this._t('seal_3', { p: m.dec.r3.pred, a: k14 }),
                this._t('seal_4', { p: this._num1(m.dec.r4.pred), a: this._num1(r.A) })
            ].map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var lo = this._loStatus(m);
            var marks = ['✗', '◐', '✓'];
            var cls = ['is-miss', 'is-part', 'is-met'];
            var los = lo.map(function(s, i) {
                return '<div class="nr-lo-row"><span class="nr-lo-mark ' + cls[s] + '" aria-hidden="true">' + marks[s] + '</span><span><strong>' + self._t('lo' + (i + 1) + '_t') + '</strong> ' + self._t('lo_st_' + s) + '</span></div>';
            }).join('');
            var notes = [];
            for (var k = 1; k <= C.ROUNDS; k++) {
                var v = dec['r' + k];
                if (v && v.note) notes.push('<li><strong>' + this._t('stage' + k) + ':</strong> ' + this._esc(v.note) + '</li>');
            }
            var html = '<div class="nr-mir-top"><span class="nr-mir-score">' + comp + '<span class="nr-mir-max">/100</span></span><span class="nr-mir-verdict">' + this._t('v_' + tier) + '</span></div>'
                + '<div class="nr-mir-sub"><span>' + this._t('cm_outcome', { n: Math.round(r.o.o) }) + '</span><span>' + this._t('cm_process', { n: Math.round(r.P) }) + '</span><span>' + this._t('cm_kpis', { k: k14, s: Math.round(r.S), a: this._num1(r.A), x: this._money(Math.round(r.X) * 1000) }) + '</span></div>'
                + '<div><h3>' + this._t('mir_14_t') + '</h3><div class="nr-people" role="img" aria-label="' + this._t('fourteen_aria', { k: k14 }) + '" style="background-color:#1b2d52;padding:10px;border-radius:4px">' + people + '</div></div>'
                + '<div><h3>' + this._t('mir_chart_t') + '</h3>' + this._chartSVG(m) + '</div>'
                + '<div class="nr-turn' + (clean ? ' is-clean' : '') + '"><h3>' + this._t('mir_turn_t') + '</h3><p>' + turn + '</p></div>'
                + '<div><h3>' + this._t('mir_ins_t') + '</h3><ul>' + ins + '</ul></div>'
                + '<div><h3>' + this._t('mir_seal_t') + '</h3><ul>' + seals + '</ul></div>'
                + '<div><h3>' + this._t('mir_lo_t') + '</h3>' + los + '</div>'
                + '<div><h3>' + this._t('mir_q_t') + '</h3><ol>' + qs + '</ol></div>';
            if (notes.length) html += '<div><h3>' + this._t('mir_notes_t') + '</h3><ul>' + notes.join('') + '</ul></div>';
            html += '<p class="nr-help">' + this._t('mir_replay') + '</p>';
            return html;
        }

        _esc(s) {
            return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        }

        /* ---------------- i18n and formatting ---------------- */

        _lang() {
            try {
                if (window.vcI18n && window.vcI18n._lang) return String(window.vcI18n._lang).slice(0, 2).toLowerCase();
            } catch (e) { return 'en'; }
            var h = (document.documentElement && document.documentElement.lang) || 'en';
            return String(h).slice(0, 2).toLowerCase();
        }

        _interp(raw, vars) {
            var out = String(raw);
            if (!vars) return out;
            Object.keys(vars).forEach(function(n) {
                out = out.split('{' + n + '}').join(String(vars[n]));
            });
            return out;
        }

        _t(key, vars) {
            if (!this._tr) this._tr = this.getTranslations();
            var lang = this._lang();
            var dict = this._tr[lang] || this._tr.en;
            var raw = dict[key];
            if (raw === undefined) raw = this._tr.en[key];
            if (raw === undefined) return key;
            return this._interp(raw, vars);
        }

        _grp(n) {
            var s = String(Math.round(Math.abs(n)));
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            while (s.length > 3) {
                out = sep + s.slice(-3) + out;
                s = s.slice(0, -3);
            }
            return s + out;
        }

        _money(n) {
            var v = Number(n) || 0;
            var sign = v < 0 ? '−' : '';
            if (this._lang() === 'es') return sign + this._grp(v) + ' USD';
            return sign + '$' + this._grp(v);
        }

        _num1(x) {
            var v = Math.round((Number(x) || 0) * 10) / 10;
            var s = String(v);
            if (this._lang() === 'es') s = s.split('.').join(',');
            return s;
        }

        _pct0(x) {
            var v = Math.round(Number(x) || 0);
            return this._lang() === 'es' ? (v + ' %') : (v + '%');
        }

